import sys

def solve():
    try:
        line = sys.stdin.read().split()
    except Exception:
        return

    if not line:
        return

    N = int(line[0])
    A = [int(x) for x in line[1:]]

    # Check for any triplet A[i] == A[i+1] == A[i+2]
    for i in range(N - 2):
        if A[i] == A[i+1] and A[i+1] == A[i+2]:
            print("Yes")
            return

    print("No")

if __name__ == "__main__":
    solve()

